flashConversationPrompt.responseSchema:
{
  "type": "object",
  "description": "Companion conversation output — response, UI, routing, enriched query",
  "required": [
    "intent",
    "enrichedQuery"
  ],
  "properties": {
    "intent": {
      "type": "string",
      "description": "Per-turn intent signal for backend routing.",
      "enum": [
        "DATA_INPUT",
        "WHAT_IF",
        "CORRECTION",
        "QUESTION",
        "GOAL_CHANGE",
        "GOAL_QUERY",
        "GREETING",
        "ACKNOWLEDGMENT"
      ]
    },
    "conversationMeta": {
      "type": "string",
      "description": "The goal journey type the user's current turn maps to. Null if no journey detected yet.",
      "nullable": true,
      "enum": [
        "EMERGENCY_FUND_SETUP",
        "HOUSE_PURCHASE_PLANNING",
        "VEHICLE_PURCHASE_PLANNING",
        "TERM_INSURANCE",
        "HEALTH_INSURANCE",
        "CHILD_EDUCATION_FUND_PLANNING",
        "WEDDING_FUND_PLANNING",
        "SABBATICAL_RUNWAY_PLANNING",
        "DEBT_CONSOLIDATION_PAYOFF_PLAN",
        "RETIREMENT_PLANNING"
      ]
    },
    "enrichedQuery": {
      "type": "string",
      "description": "Contextually refined, self-contained version of the user's message. Resolves pronouns, expands implicit context, includes relevant user profile details. One to three sentences."
    },
    "thinkingText": {
      "type": "string",
      "description": "Temporary placeholder shown to the user while the Planner works. Emitted ONLY when escalation.needed = true — mutually exclusive with uiIntent. References the topic without predicting the answer. One sentence, present progressive, ends with ellipsis.",
      "nullable": true
    },
    "assistantText": {
      "type": "string",
      "description": "Execution log for chatHistory continuity — next-turn LLM reads this to know what happened structurally. MUST include: (1) display intents emitted as `Present: resultKind, title`, (2) escalation actions as `Escalated: deviationType, reason=...`. NOT user-facing."
    },
    "uiIntent": {
      "description": "Semantic UI intent. Null on escalation turns (thinkingText is emitted instead).",
      "type": "object",
      "nullable": true,
      "required": ["message"],
      "properties": {

        "message": {
          "type": "string",
          "description": "Conversational text to the user. Always required."
        },

        "present": {
          "type": "array",
          "description": "Display intents. Each entry becomes one display component via the Resolver. Optional — only when a visual genuinely helps.",
          "nullable": true,
          "maxItems": 1,
          "items": {
            "type": "object",
            "required": ["resultKind", "title"],
            "properties": {

              "resultKind": {
                "type": "string",
                "enum": ["KPI", "STATUS", "CONFIRMATION", "ALLOCATION", "PLAN"],
                "description": "What this display block represents."
              },

              "entityMeta": {
                "type": "object",
                "description": "Entity context for this display block. Required when the display is entity-scoped (e.g., showing a specific person's goal status). Null for aggregate or plan-level displays.",
                "nullable": true,
                "properties": {
                  "entityGroupId": {
                    "type": "string",
                    "description": "Entity group this display relates to (e.g., 'person_1', 'household_1')."
                  },
                  "relationshipToUser": {
                    "type": "string",
                    "enum": ["SELF", "SPOUSE", "PARENT", "CHILD", "HOUSEHOLD", "SIBLING", "OTHER"],
                    "description": "The entity's relationship to the primary user."
                  }
                }
              },

              "title": {
                "type": "string",
                "description": "Card header."
              },

              "headline": {
                "type": "object",
                "nullable": true,
                "required": ["value", "subtitle"],
                "properties": {
                  "value": { "type": "string" },
                  "subtitle": { "type": "string" }
                }
              },

              "items": {
                "type": "array",
                "nullable": true,
                "items": {
                  "type": "object",
                  "required": ["label", "value"],
                  "properties": {
                    "label": { "type": "string" },
                    "value": { "type": "string" },
                    "detail": { "type": "string", "nullable": true },
                    "indicator": { "type": "string", "nullable": true },
                    "icon": { "type": "string", "nullable": true }
                  }
                }
              }
            }
          }
        }
      }
    },
    "escalation": {
      "type": "object",
      "description": "Escalation signal to the Planner. Null if no escalation needed.",
      "nullable": true,
      "properties": {
        "needed": {
          "type": "boolean",
          "description": "True if this turn requires Planner involvement"
        },
        "reason": {
          "type": "string",
          "description": "Prose description of why escalation is needed and the conversational context."
        },
        "deviationType": {
          "type": "string",
          "description": "Category of deviation that triggered escalation",
          "enum": [
            "GOAL_REQUIRES_DECOMPOSITION",
            "HIGH_CONSEQUENCE_RECOMMENDATION",
            "GOAL_CHANGE",
            "UNRESOLVABLE_AMBIGUITY",
            "BEYOND_KNOWLEDGE_BASE",
            "EMOTIONAL_DISTRESS",
            "CONTRADICTION"
          ],
          "nullable": true
        },
        "goalContextFetch": {
          "type": "object",
          "description": "Instructs the backend router to fetch and hydrate enriched goal context for the specified goals before invoking the Planner. Only meaningful when needed=true.",
          "nullable": true,
          "properties": {
            "focusGoals": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Goal IDs (from T1 portfolio) that the Planner should receive enriched context for."
            },
            "tier": {
              "type": "string",
              "enum": [
                "STANDARD",
                "DEEP"
              ],
              "description": "STANDARD = Tier 1 + Tier 2. DEEP = Tier 1 + Tier 2 + Tier 3."
            }
          }
        }
      }
    }
  }
}
